click.script:
const addonRate = pricingView.data.addon_rate || 0;
const chosenAddons = (pricingView.data.addons || []).filter(a => (selectedAddons.value || []).includes(a.name));
const addonsPreGST = chosenAddons.reduce((s, a) => s + (a.typical_hours || 0) * addonRate, 0);
const total = addonsPreGST * 1.18;
const payload = chosenAddons.map(a => ({ name: a.addon_name, price: Math.round((a.typical_hours || 0) * addonRate * 1.18) }));
call('connect.api.save_price_estimate', {
  partner: partner.doc.name,
  requirement: pricingView.data.requirement || null,
  selected_addons: payload,
  total: Math.round(total),
}).then((name) => {
  let summary = 'Estimating at hourly rate (\u20b9' + Number(pricingView.data.rate || 0).toLocaleString('en-IN') + '/hr)';
  if (chosenAddons.length) {
    summary += ' + ' + chosenAddons.map(a => a.addon_name).join(', ');
  }
  summary += '. Estimated total: \u20b9' + Math.round(total).toLocaleString('en-IN') + '.';
  return call('connect.api.start_partner_thread', { partner: partner.doc.name, message: summary });
}).then(() => {
  router.push('/messaging-d87b');
}).catch((err) => {
  toast({ title: 'Could not start conversation', text: (err && err.message) || 'Please try again', icon: 'x' });
});

